// Ongoing effects drawn by the "effects" module. `turns` = how many of the
// player's own turns the effect lasts.
const e = (id, title, body, turns = 1, extra = {}) => ({
  id: `sys-ef-${id}`,
  title,
  body,
  turns,
  category: 'Ефект',
  modes: ['any'],
  tags: [],
  ...extra,
})

